    "yasaStory": "아티스 왕이 다스리던 시절, 리디아 전역에 잔인한 가뭄과 기근이 덮쳤다. 메마른 땅에서 곡식이 사라지자 백성들은 굶주림에 허덕였다. 왕과 백성들은 고통을 덜기 위해 기상천외한 생존법을 고안해 냈다. 하루는 밥을 짓지 않는 대신 종일 놀이에 빠져들고, 이튿날에야 허기진 배를 채우기로 한 것이다.\n\n이 지독한 배고픔 속에서 주사위, 동물 복사뼈 놀이, 공놀이 등 인류 최초의 온갖 유희가 탄생했다. 온 나라 사람들이 아침부터 광장에 둘러앉아 패를 쥐고 주사위를 굴리며 승패에 목을 맸다. 게임의 스릴에 도취해 있는 동안에는 뱃속에서 요동치는 굶주림의 고통도 까맣게 잊을 수 있었다.\n\n그들은 놀이로 헛배를 채우며 무려 18년의 기근을 버텼다. 마침내 더 이상 버틸 수 없게 되자, 제비를 뽑아 백성의 절반이 티레니아인의 조상이 되어 서쪽 이탈리아 바다로 떠났다. 놀이는 단순한 유흥이 아니라 극한의 절망을 이겨내기 위한 절박한 생존의 방패였다."
