    "yasaStory": "리디아의 마지막 헤라클레스 왕조 군주 칸다울레스는 자기 왕비의 미모에 푹 빠져 있었다. 그는 총애하던 경호대장 기게스에게 틈만 나면 왕비가 세상에서 가장 아름답다고 자랑하다가, 급기야 믿지 못하겠다면 직접 두 눈으로 보라고 강요했다. \"사람은 귀보다 눈을 더 믿는 법\"이라며 침실 문 뒤에 숨어 옷을 벗는 왕비를 엿보게 한 것이다.\n\n기게스가 사양해도 왕의 명령을 거스를 수 없었다. 그날 밤 기게스는 문 뒤에 숨어 왕비가 옷을 벗는 모습을 보고 조용히 빠져나갔다. 하지만 왕비는 그림자가 스쳐 가는 것을 알아챘고, 남편이 꾸민 일임을 직감한 채 수치심에 불타면서도 밤새 아무 내색도 하지 않았다.\n\n이튿날 왕비는 기게스를 불러 단도와 함께 두 갈래 길을 내밀었다. \"나를 알몸으로 본 죄로 지금 죽거나, 칸다울레스를 죽이고 나와 리디아의 왕위를 차지하라.\" 살기 위해 기게스는 어젯밤 숨었던 그 문 뒤에 다시 섰고, 잠든 왕을 찔러 새 왕조를 열었다."
