    "title": "섬사람들이 말을 탄다면?… 바다 원정을 멈춘 현자의 꾀",
    "officialRecord": "이오니아의 현자 비아스는 에게해 섬사람들이 기병을 모아 본토를 치려 한다는 기발한 헛소문으로 크로이소스에게 해전의 위험성을 일깨워 무모한 해상 침공을 포기하게 만들었다.",
    "source": "헤로도토스 《역사》 제1권",
    "sillokUrl": "https://en.wikipedia.org/wiki/Bias_of_Priene",
