    "officialRecord": "스파르타가 동맹을 맺은 크로이소스 왕에게 바치려 보낸 300암포라 규모의 거대한 청동 믹싱 볼은 사모스 섬 인근에서 사라져 양국 간 치열한 책임 공방을 낳았다.",
