    "yasaStory": "스파르타인들은 막강한 부와 권력을 자랑하는 리디아의 크로이소스 왕과 동맹을 맺은 뒤, 감사의 뜻으로 지상에서 가장 웅장한 선물을 마련했다. 300암포라의 포도주를 한꺼번에 담을 수 있는 거대한 청동 솥이었다. 솥의 둘레는 정교하게 조각된 온갖 짐승의 문양으로 가득 차 감탄을 자아냈다.\n\n그러나 이 거대한 보물은 사르디스 궁정에 끝내 닿지 못했다. 수송선이 사모스 섬 근처를 지날 때 감쪽같이 사라져 버린 것이다. 스파르타인들은 사모스 해적들이 나타나 배를 약탈하고 보물을 강탈했다고 분통을 터뜨렸다. 반면 사모스인들은 스파르타의 사절들이 너무 늦게 도착하는 바람에 크로이소스가 페르시아에 패망했다는 소식을 듣고, 보물을 몰래 사모스 시장에 헐값으로 팔아넘겼다고 반박했다.\n\n진실이 무엇이든 이 거대한 청동 솥은 사모스 섬의 헤라 신전에 봉헌물로 당당히 전시되었다. 천하를 호령하던 부자 왕 크로이소스의 몰락과 함께, 그를 위해 빚어진 불멸의 걸작은 엉뚱한 신전의 뜰에서 사람들의 구경거리가 되고 말았다."
