    "officialRecord": "페르시아의 지배에 굴복하기를 거부한 포카이아 시민들은 바닷속에 시뻘겋게 단 쇳덩이를 던지며 쇠가 물에 뜰 때까지 고향에 돌아오지 않겠다는 맹세를 남기고 도시 전체가 탈출했다.",
