    "officialRecord": "카스피해 동쪽의 마사게타이족은 철과 은을 쓰지 않고 황금과 청동으로 무기를 만들었으며, 늙은 부모를 희생제물로 바쳐 고기를 나눠 먹는 것을 인간 최고의 행복으로 여겼다.",
