    "yasaStory": "테르모필레를 돌파한 크세르크세스는 아폴론 신전의 막대한 보물을 빼앗기 위해 별동대를 델포이로 보냈다. 공포에 질린 델포이 주민들이 신에게 보물을 옮겨야 할지 묻자, 신탁은 '신께서 스스로의 것을 지키실 것'이라 답했다.\n\n페르시아군이 아테나 프로나이아 신역에 닿았을 때 기이한 일이 벌어졌다. 신전 안에 두었던 성스러운 무구들이 어느새 문 밖에 나와 놓여 있었고, 맑던 하늘에서 갑자기 벼락이 떨어져 적진을 강타했다.\n\n이어 파르나소스 산봉우리에서 거대한 바위 두 개가 굉음을 내며 떨어져 내려 수많은 페르시아 병사를 덮쳤고, 신전 안에서는 거대한 함성이 울려 퍼졌다. 공황에 빠진 페르시아군은 뿔뿔이 도주했고, 헤로도토스는 자신이 델포이 신역에서 그 부서진 바위들을 직접 보았다고 기록했다."
