    "category": "scandal",
    "interestScore": 88,
    "title": "공정한 재판관으로 민심을 얻어 철권 군주가 된 데이오케스",
    "officialRecord": "무법천지였던 메디아에서 공정한 중재자로 명성을 쌓은 데이오케스가 돌연 재판을 거부해 혼란을 부추긴 뒤, 추대를 받아 왕위에 올라 일곱 겹 성채에 군림한 일화다.",
    "source": "헤로도토스 《역사》 제1권",
