    "imageUrl": "https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7f/The_story_of_the_greatest_nations%3B_a_comprehensive_history%2C_extending_from_the_earliest_times_to_the_present%2C_founded_on_the_most_modern_authorities%2C_and_including_chronological_summaries_and_%2814780857854%29.jpg/960px-thumbnail.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail",
    "yasaStory": "아시리아의 지배에서 벗어난 메디아는 법도 질서도 없는 무법천지였다. 이때 야심가 데이오케스는 마을의 분쟁을 누구보다 공정하고 지혜롭게 판결하며 명성을 얻기 시작했다. 사방에서 사람들이 그에게 재판을 받으러 몰려들자, 어느 날 그는 돌연 선언했다. \"남의 송사만 돌보다 내 살림이 거덜 나겠소. 이제 그만두겠소.\"\n\n그가 물러나자 약탈과 무법이 전보다 몇 배나 극심해졌다. 결국 궁지에 몰린 메디아인들은 \"이대로는 살 수 없으니 왕을 세우자\"며 데이오케스를 초대 왕으로 추대했다. 바로 그가 치밀하게 노리던 순간이었다.\n\n왕관을 쓰자마자 데이오케스는 태도를 180도 바꿨다. 호위병과 장엄한 궁전을 요구하더니, 수도 엑바타나에 색깔이 다른 일곱 겹의 성벽을 쌓고 가장 안쪽에 틀어박혔다. 백성은 물론 옛 동료들조차 왕의 얼굴을 직접 볼 수 없었고, 왕 앞에서 웃거나 침을 뱉는 일마저 엄금되어 철저한 신비주의 절대 권력이 탄생했다."
