    "title": "어머니의 멍에를 메고 영원한 잠의 축복을 받은 두 형제",
    "officialRecord": "헤라 여신전 축제에 늦지 않도록 소 대신 어머니의 달구지를 끌고 45스타디온을 달린 클레오비스와 비톤 형제는 신이 인간에게 내린 가장 고귀한 선물인 평온한 영면에 들었다.",
