    "yasaStory": "리디아의 궁전을 방문한 아테네의 현자 솔론에게 크로이소스 왕은 지하 깊숙한 보물창고를 열어 보였다. 번쩍이는 황금 잉곳과 진귀한 패물들을 뽐낸 뒤, 왕은 은근한 기대를 품고 물었다. \"그대가 세상에서 본 사람들 중 가장 행복한 자는 누구였소?\" 당연히 자신의 이름이 나오리라 믿었던 것이다.\n\n그러나 솔론의 입에서 나온 이름은 엉뚱하게도 아테네의 무명 시민 '텔로스'였다. 충격을 받은 왕이 그 이유를 묻자 솔론은 담담히 설명했다. \"텔로스는 번영하는 조국에서 태어나 훌륭한 자식들을 보았고, 손자들의 탄생까지 모두 지켜보았습니다. 남부럽지 않은 살림을 누리다 조국의 전쟁터에서 적을 물리치고 영예롭게 전사하여 국장으로 묻혔습니다.\"\n\n솔론은 인생의 마지막 순간이 어떻게 끝날지 모르는 이상, 부유하다고 해서 행복하다고 단정할 수 없다고 경고했다. 눈앞의 황금에 취해 오만했던 크로이소스는 현자의 경고를 비웃었지만, 머지않아 왕국을 잃고 화형대 위에서야 눈물로 솔론의 이름을 부르짖게 된다."
