    "officialRecord": "테게아를 정복해 노예로 삼겠다며 미리 족쇄를 차고 출정한 스파르타 병사들은 오만한 방심 끝에 대패하여 자신들이 가져온 족쇄에 묶여 테게아의 밭을 가는 치욕을 겪었다.",
