    "yasaStory": "펠로폰네소스반도의 패권을 노리던 스파르타인들은 델포이 신전으로부터 '테게아의 평야를 측량 줄로 재고 그곳에서 춤추게 되리라'는 신탁을 받았다. 오만에 빠진 스파르타인들은 승리를 의심치 않았다. 그들은 적군을 사로잡아 곧바로 노예로 삼겠다며 출전하는 군장 속에 쇠 족쇄를 한 짐씩 챙겨 넣었다.\n\n그러나 결사항전으로 맞선 테게아의 군세는 스파르타의 예상을 아득히 뛰어넘었다. 치열한 백병전 끝에 스파르타군은 처참하게 무너졌고, 살아남은 병사들은 고스란히 포로로 사로잡혔다. 테게아인들은 스파르타인들이 허리춤에 차고 온 바로 그 쇠 족쇄를 꺼내 그들의 발목에 철컥 채웠다.\n\n스파르타 병사들은 제 발목에 감긴 족쇄를 끌며 테게아 평야의 거친 흙을 갈아엎어야 했다. 신탁이 예언했던 '측량 줄'은 밭을 일구는 노예의 줄이었고, '춤'은 족쇄에 묶여 절뚝거리는 노예의 발짓이었던 것이다. 신탁의 뜻을 제멋대로 해석한 자들에게 내린 가혹한 운명의 조롱이었다."
