    "yasaStory": "페르시아의 부흥에 위기감을 느낀 크로이소스 왕은 그리스 전역의 신탁소들을 시험한 끝에 오직 델포이의 아폴론만이 진실을 안다고 확신했다. 신의 확고한 가호를 사기 위해 왕은 사상 유례없는 거대한 제물을 마련했다. 살진 가축 3,000마리를 제단에 바치고, 황금 침대와 진홍빛 옷을 불태워 연기를 피워 올렸다.\n\n그것도 모자라 그는 엄청난 양의 금을 녹여 가로 세로 규격이 일정한 금 벽돌 117개를 만들었다. 그중 넷은 불순물이 전혀 섞이지 않은 순금 벽돌이었다. 그리고 그 순금 벽돌들 위에 무게만 열 달란트에 달하는 눈부신 황금 사자상을 얹어 델포이 성소로 보냈다. 사자상과 함께 거대한 은 항아리와 금 항아리도 보내졌다.\n\n델포이 신전 전체가 리디아 왕이 보낸 황금빛으로 번쩍였다. 사제들은 환호하며 '강을 건너면 대제국이 멸망하리라'는 애매한 신탁을 내렸다. 크로이소스는 그 제국이 페르시아일 것이라 굳게 믿었으나, 정작 파멸한 제국은 황금을 쏟아부었던 자신의 왕국이었다."
