    "yasaStory": "도망자 팍티에스를 숨겨둔 키메인들은 페르시아의 보복이 두려워 밀레토스의 디디마 신전에 신탁을 구했다. 신탁은 뜻밖에도 '팍티에스를 페르시아인들에게 넘겨주라'는 답을 내렸다. 의로운 시민 아리스토디코스는 사제들이 뇌물을 받고 거짓을 말하는 것이라 의심하며 직접 두 번째 사절단을 이끌고 신전을 찾았다.\n\n아리스토디코스는 아무 말 없이 신전 회랑을 돌며 처마 밑에 깃든 참새와 제비 둥지를 마구 털어냈다. 그러자 성소 깊은 곳에서 아폴론의 노기 띤 음성이 메아리쳤다. \"가장 불경한 자여! 감히 내 신전에 피신한 자식들을 내 눈앞에서 약탈하려 드느냐?\"\n\n아리스토디코스가 기다렸다는 듯 외쳤다. \"신이시여, 당신은 하찮은 새끼 새도 지키시면서 어찌 우리에게 피신 온 망명자를 넘기라 명하십니까?\" 그러자 신전에서 서늘한 답이 떨어졌다. \"그렇다! 너희가 신탁을 핑계로 불경한 죄를 짓고 하루빨리 멸망하여, 다시는 도망자를 배신하는 법을 묻지 못하게 하려는 것이다!\" 비겁한 타협을 꾸짖는 신의 일갈이었다."
