    "officialRecord": "탈레스가 예언했던 개기일식이 메디아와 리디아 군대의 격전 도중 하늘을 암흑으로 뒤덮자, 신의 분노에 전율한 양국은 칼을 거두고 즉시 혼인 동맹을 맺었다.",
