    "yasaStory": "리디아의 알리아테스 왕과 메디아의 키악사레스 왕은 영토를 둘러싸고 무려 6년 동안 지루하고 피비린내 나는 전쟁을 이어갔다. 승패를 가리지 못한 채 수많은 병사의 피가 할리스강 유역을 적시던 어느 날, 양군이 진형을 갖추고 마주선 격전의 순간 상상치 못한 기적이 일어났다.\n\n한낮의 태양이 갑자기 빛을 잃더니 온 세상이 칠흑 같은 암흑 속으로 빠져든 것이다. 이 기이한 천문 현상은 밀레토스의 철학자 탈레스가 그해 일어날 것이라 예언했던 개기일식이었다. 하지만 전쟁터의 병사들에게 그것은 신들이 당장 칼을 거두라고 내리는 무서운 하늘의 징벌로 보였다.\n\n공포에 질린 병사들은 무기를 내던졌고, 두 왕은 신의 분노를 달래기 위해 즉시 휴전을 선언했다. 그들은 단순히 평화 조약을 맺는 데 그치지 않고, 알리아테스의 딸 아리에니스를 메디아 왕세자 아스티아게스와 혼인시켜 영원한 화친을 맹세했다. 우주의 신비가 인간의 맹목적인 살육을 단숨에 멈춰 세운 순간이었다."
