    "yasaStory": "메디아의 마지막 왕 아스티아게스는 외손자 키루스가 자신을 몰아낼 것이라는 꿈을 꾸고, 측근 하르파고스에게 갓난아기를 죽이라 명했다. 하지만 차마 손에 피를 묻히기 싫었던 하르파고스는 목동에게 아이를 넘겼고, 목동 부부가 몰래 아이를 키우면서 키루스는 열 살까지 무사히 자랐다.\n\n뒤늦게 진실을 알게 된 아스티아게스는 분노를 꾹 삼킨 채 겉으로는 용서하는 척하며 하르파고스를 성대한 연회에 초대했다. 그리고 하르파고스의 어린 아들을 궁으로 불러들여 토막 내고 삶고 구워, 아무것도 모르는 아버지의 식탁에 고기 요리로 올렸다.\n\n하르파고스가 배불리 식사를 마치자 시종들이 뚜껑 덮인 바구니를 내밀었다. 그 안에는 아들의 머리와 손발이 담겨 있었다. 왕이 웃으며 무슨 고기를 먹었는지 아느냐고 묻자, 하르파고스는 핏기 가신 얼굴로 떨리는 입술을 깨물며 답했다. \"왕께서 하시는 일은 무엇이든 옳습니다.\" 그러나 그 침묵 속에는 제국을 무너뜨릴 복수의 칼날이 갈리고 있었다."
