    "title": "목동 부부 밑에서 자라며 '왕 놀이'로 본색을 드러낸 키루스",
    "officialRecord": "태어나자마자 버려질 뻔한 키루스가 죽은 아기와 바꿔치기한 목동 부부의 손에 자라다가, 열 살 때 '왕 놀이'에서 귀족 아들을 매질한 일로 친아들임이 밝혀진 이야기다.",
