    "officialRecord": "아스티아게스 왕의 살해 명령을 받은 아기 키루스는 마침 사산아를 낳았던 산골 양치기 미트라다테스 부부의 눈물겨운 모성 덕에 시신을 맞바꿔 목숨을 건졌다.",
