    "yasaStory": "시골 양치기의 아들로 자라던 열 살의 키루스는 골목길에서 동네 아이들과 함께 '왕 놀이'를 했다. 아이들은 가장 당당하고 영민한 키루스를 왕으로 뽑았다. 키루스는 아이들에게 궁궐을 짓고 호위병과 전령을 맡기는 등 엄격한 법도를 세워 골목길을 통치했다.\n\n그런데 메디아의 최고 귀족 아르템바레스의 아들이 양치기 아들의 명령을 우습게 여기고 복종을 거부했다. 키루스는 추호의 망설임도 없이 부하들에게 명해 소년을 붙잡게 한 뒤, 가죽 채찍으로 등을 호되게 후려쳤다. 분노한 귀족은 왕 아스티아게스에게 달려가 천한 양치기 놈이 고관의 자식을 모욕했다고 울분을 토했다.\n\n왕 앞에 끌려온 어린 키루스는 주눅 들기는커녕 두 눈을 똑바로 치켜뜨고 말했다. \"아이들이 나를 왕으로 세웠고 나는 왕으로서 율법을 어긴 신하를 벌했을 뿐입니다. 이것이 죄라면 벌을 달게 받겠습니다.\" 소년의 당당한 태도와 얼굴 윤곽을 뜯어보던 아스티아게스는 가슴이 철렁 내려앉았다. 죽은 줄 알았던 손자가 살아 돌아온 것이었다."
