    "officialRecord": "크니도스인들은 페르시아의 침략을 막으려 좁은 지협을 파내 반도를 섬으로 만들려 했으나, 튀는 돌 파편에 인부들의 눈이 다치자 신탁의 명에 따라 공사를 포기했다.",
