    "yasaStory": "천하를 호령하던 신바빌로니아 제국의 마지막 왕 나보니두스는 상식을 벗어난 기이한 군주였다. 그는 바빌론의 수호신인 마르두크 신전을 돌보는 일에는 관심이 없었고, 오직 어머니가 섬기던 하란의 달의 신 '신(Sin)'을 숭배하는 데 온 정신이 팔려 있었다.\n\n사제들과의 갈등이 극에 달하자 왕은 바빌론 도성을 아들 벨사살에게 내맡기고, 천 리 길을 달려 아라비아 사막 한가운데의 타이마 오아시스로 떠나버렸다. 그곳에서 그는 무려 십 년 동안이나 도성에 발을 들이지 않은 채 달의 신전을 짓고 은둔했다. 바빌론의 신년 축제는 끊겼고 백성들과 사제들의 원망은 하늘을 찔렀다.\n\n키루스가 이끄는 페르시아 대군이 성벽 아래로 들이닥쳤을 때, 바빌론 사람들은 왕을 위해 칼을 들지 않았다. 사제들은 오히려 키루스를 마르두크 신이 보낸 해방자로 환영하며 성문을 활짝 열어주었다. 사막의 달그림자를 쫓던 몽상가 군주는 제국의 허망한 몰락을 무력하게 지켜보아야 했다."
