    "officialRecord": "페르시아 귀족들은 아들이 다섯 살부터 스무 살이 될 때까지 오직 말을 타고 활을 쏘며 거짓말을 하지 않는 세 가지만을 가장 숭고한 덕목으로 가르쳤다.",
