    "yasaStory": "대제국을 건설한 페르시아의 귀족 사회는 어린 소년들을 양육하는 방식부터 남달랐다. 사내아이가 태어나면 다섯 살이 될 때까지 아버지의 얼굴을 보지 못하고 오직 어머니와 유모들의 방에서만 자라났다. 행여 아이가 요절하더라도 아버지가 슬픔에 젖지 않게 하려는 배려였다.\n\n다섯 살이 되면 소년들은 혹독한 귀족 교육에 들어갔다. 스무 살이 될 때까지 십오 년 동안 배우는 것은 오직 세 가지뿐이었다. 준마의 등 위에서 바람처럼 달리는 '말타기', 백발백중으로 적의 심장을 꿰뚫는 '활쏘기', 그리고 어떤 상황에서도 거짓을 입에 담지 않는 '진실 말하기'였다.\n\n페르시아인들은 세상에서 가장 수치스러운 죄악으로 거짓말을 꼽았고, 그다음으로는 빚을 지는 것을 경멸했다. 빚을 진 자는 필연적으로 채권자에게 거짓말을 둘러대게 된다는 이유에서였다. 진실에 대한 엄격한 숭상과 강인한 무예가 바로 변방의 소국이었던 페르시아를 세계의 제국으로 밀어 올린 숨은 원동력이었다."
