    "yasaStory": "키루스 대제는 카스피해 동쪽의 마사게타이를 굴복시키기 위해 비열한 덫을 놓았다. 포도주를 마셔본 적 없는 유목민들의 약점을 노려, 막사에 기름진 고기와 물을 타지 않은 독한 포도주를 가득 차려놓고 약한 병사들만 남겨둔 채 후퇴한 것이다.\n\n여왕 토미리스의 아들 스파르가피세스 왕자가 이끄는 마사게타이의 정예 선봉대가 막사를 급습했다. 손쉬운 승리에 도취한 왕자와 병사들은 달콤한 포도주를 물처럼 들이켰다. 온 군대가 술에 취해 곯아떨어지자 매복해 있던 페르시아군이 덮쳤다. 병사들은 살육당했고 왕자는 포승줄에 묶였다.\n\n술이 깨어 결박된 자신과 몰살당한 부하들을 본 스파르가피세스는 견딜 수 없는 수치심에 몸을 떨었다. 그는 키루스에게 결박을 풀어달라고 담담히 청했다. 포박이 풀려 두 손이 자유로워진 순간, 젊은 왕자는 망설임 없이 곁에 있던 칼을 빼내 제 목을 찔렀다. 술 덫에 걸린 오욕을 목숨으로 씻어낸 비극이었다."
