    "yasaStory": "주민들이 모두 떠난 텅 빈 아테네를 점령한 페르시아군은 아크로폴리스에 불을 질렀다. 에레크테우스 신전과 함께 여신 아테나가 아테네인들에게 선물했다고 전해지는 성스러운 올리브 나무도 시커먼 재로 변하고 말았다.\n\n그런데 페르시아군의 뒤를 따라 아크로폴리스에 올라 제사를 지내던 아테네 망명객들은 믿을 수 없는 광경을 목격했다. 불과 전날까지만 해도 불길에 휩싸여 완전히 타버렸던 그 올리브 나무 밑동에서 하룻밤 사이에 팔꿈치 길이(약 45센티미터)나 되는 푸른 새순이 솟아 나와 있었던 것이다.\n\n폐허 위에서 피어난 이 기적의 새싹은 비록 도시는 잿더미가 되었을지라도 아테네의 생명력과 여신의 가호는 결코 꺼지지 않았음을 알리는 희망의 징표로 전해졌다."
