    "yasaStory": "그리스를 비롯한 지중해 세계에서 따뜻한 양모는 귀한 대접을 받았지만, 나일강의 이집트인들에게 짐승의 털은 불결함의 상징이었다. 그들은 살아있는 짐승의 가죽이나 털에서 나오는 분비물이 신성한 영혼을 더럽힌다고 믿었다. 따라서 신전에 들어가는 사제들은 반드시 갓 세탁한 순백의 아마포 옷만을 몸에 둘렀다.\n\n사제들의 결벽증은 상상을 초월했다. 이틀에 한 번씩 온몸의 털을 남김없이 깎아 이나 벼룩이 숨을 틈을 주지 않았고, 하루에 네 번씩 찬물로 몸을 씻었다. 신발조차 오직 파피루스로 엮은 것만 허용되었다. 겉옷으로 양모 외투를 걸치는 일반인조차 신전 경내에 발을 디딜 때는 반드시 양모를 벗어던져야 했다.\n\n이 엄격한 금기는 죽음의 문턱에서도 이어졌다. 미라를 감싸는 수의는 오직 정갈한 아마포 붕대여야 했으며, 무덤 속에 양모로 짠 직물을 넣는 것은 고인의 영원한 안식을 망치는 신성모독으로 간주되었다. 순백의 아마포는 신 앞에 서는 인간의 가장 순결한 예의였다."
