    "yasaStory": "나일강변의 고도 멤피스에는 인간 왕보다 더 큰 존경과 호사를 누리는 살아있는 신이 있었다. 프타 신의 화신으로 받들어지던 성스러운 검은 황소 '아피스'였다. 전설에 따르면 이 황소는 하늘에서 내려온 번갯불을 맞은 암소가 수태하여 낳는다고 전해졌다.\n\n아피스로 공인받기 위한 조건은 믿을 수 없을 만큼 까다로웠다. 사제들은 전국을 돌며 갓 태어난 송아지들을 샅샅이 조사했다. 온몸의 털은 칠흑처럼 검어야 하되, 이마에는 반듯한 흰 삼각형 얼룩이 있어야 했고, 등 뒤에는 날개를 펼친 독수리 문양이, 꼬리에는 두 가닥 털이, 그리고 혀 밑에는 쇠똥구리 모양의 돌기가 돋아 있어야 했다.\n\n이 모든 징표를 갖춘 송아지가 발견되면 온 이집트가 축제의 도가니에 빠졌다. 황소는 황금으로 치장된 호화로운 궁전에서 암소 하렘을 거느리며 최고급 곡물을 먹고 살았다. 살아 숨 쉬는 신을 직접 눈으로 보며 위안을 얻고자 했던 고대인들의 소박하고도 거대한 신앙이었다."
