    "yasaStory": "고대 이집트의 상류층 저택에서 성대한 잔치가 열리면, 보리로 빚은 향긋한 맥주와 포도주가 넘쳐흐르고 하프 연주에 맞추어 무희들이 춤을 추었다. 흥이 절정에 달하고 손님들이 거나하게 취했을 무렵, 연회장 문이 열리며 한 하인이 기이한 물건을 들고 나타났다.\n\n그것은 길이 1~2큐빗 남짓한 나무로 정교하게 깎아 채색한 미라 모양의 작은 목관이었다. 하인은 손님들 앞을 한 사람씩 돌아가며 차가운 목관을 내밀어 얼굴 가까이 들이댔다. 그리고 엄숙하면서도 다정한 목소리로 귓가에 속삭였다. \"이 관을 바라보십시오. 그대가 죽으면 누구나 이렇게 될 것입니다. 그러니 지금 잔을 들고 생을 마음껏 즐기십시오!\"\n\n죽음의 그림자를 들이밀어 삶의 환희를 일깨우는 기막힌 역설이었다. 죽음을 일상의 한가운데로 끌어들여 두려움을 지우고, 오늘 내 손에 쥐어진 한 잔의 술과 사랑하는 이들의 온기를 더 깊이 만끽하라는 지혜로운 조상들의 가르침이었다."
