    "yasaStory": "그리스 본토에서는 볼 수 없었던 기이한 동물들을 찾아 헤매던 헤로도토스에게 나일강의 '하마'는 가장 강렬한 인상을 남긴 생명체였다. 그는 테베 지역에서 이 거대한 짐승을 신성하게 여긴다는 소문을 듣고 현지인들의 증언을 그러모아 기록을 남겼다.\n\n그의 묘사에 따르면 하마는 네 발 달린 짐승으로 소처럼 굽이 갈라져 있고 코는 펑퍼짐하며, 말의 갈기와 말의 꼬리, 그리고 말의 울음소리를 지녔다고 했다. 입 밖으로는 멧돼지처럼 억센 엄니가 튀어나와 있었고, 가죽이 얼마나 질기고 두꺼운지 말려서 단단하게 굳히면 가공할 위력의 투창 자루를 만들 수 있다고 적었다.\n\n비록 말의 갈기가 달렸다는 묘사처럼 전해 들은 소문이 다소 섞여 과장된 면이 있었지만, 그리스인들에게 나일강 하마의 존재는 살아있는 신화 속 괴수나 다름없었다. 강둑을 뒤흔들며 진흙탕에서 솟구쳐 오르는 거대한 물말의 형상은 고대 여행자들의 가슴을 서늘한 경외감으로 물들였다."
