    "yasaStory": "세소스트리스의 뒤를 이은 페론 왕은 신을 두려워하지 않는 오만한 군주였다. 어느 날 폭풍우와 함께 나일강이 유례없이 사납게 역류하며 들판을 집어삼키자, 격노한 왕은 강 한가운데를 향해 무모하게도 손에 쥔 창을 던져버렸다.\n\n강물의 신을 모독한 죄는 즉각적이었다. 눈에 심한 안질이 찾아오며 왕은 그 자리에서 시력을 잃고 10년 동안 깊은 어둠 속에 갇혀 지내야 했다. 10년 만에 부토의 신전에서 신탁이 내려왔는데, 오직 남편 외에 다른 남자를 결코 알지 못한 정숙한 여인의 소변으로 눈을 씻어야 눈이 뜨인다는 처방이었다.\n\n왕은 가장 먼저 자신의 왕비 것으로 눈을 씻었으나 아무런 효험이 없었고, 온 나라의 귀족 부인들을 불러 시험했으나 실패했다. 마침내 한 이름 없는 평민 아내의 것으로 눈을 씻었을 때 기적처럼 눈이 밝아졌다. 분노한 왕은 부정을 저지른 왕비와 여인들을 한 성읍에 모아 불태워 죽이고, 은인인 여인을 새 왕비로 맞이했다."
