    "yasaStory": "지혜롭기로 이름난 바빌론의 여왕 니토크리스는 죽음을 앞두고 기이한 유언을 남겼다. 자신의 무덤을 바빌론에서 가장 통행량이 많은 성문 바로 위쪽에 세우게 하고, 그 겉면에 도발적인 비문을 새겨 넣은 것이다. \"후대의 바빌론 왕 중 재물이 부족한 자는 이 무덤을 열어 원하는 만큼 가져가라. 단, 정말 절박하지 않다면 절대 열지 마라.\"\n\n오랜 세월 아무도 그 무덤에 손을 대지 못하다가, 훗날 바빌론을 지배하게 된 페르시아의 다리우스 1세가 눈독을 들였다. 성문 아래를 지날 때마다 시체 밑을 통과하는 기분이 찝찝했던 데다, 눈앞에 놓인 보물을 그냥 지나치기도 아까웠기 때문이다.\n\n결국 다리우스가 무덤을 부수고 안을 들여다보았을 때, 금은보화는 단 한 푼도 없었다. 차가운 시신 옆에 놓인 또 하나의 비문만이 왕을 비웃고 있었다. \"그대가 탐욕스럽고 염치가 없는 자가 아니었다면, 죽은 자의 무덤을 함부로 열지 않았을 것이다.\""
