    "yasaStory": "아마시스 2세는 파라오가 되기 전 평민 출신으로 젊은 시절 방탕하게 술 마시고 노는 것을 좋아했다. 유흥비가 떨어지면 이웃집 담을 넘어 물건을 훔치곤 했는데, 피해자들이 그를 신탁소로 끌고 가 도둑인지 여부를 묻곤 했다.\n\n당시 어떤 신전의 신탁은 그가 도둑이 맞다고 정확히 짚어냈지만, 어떤 신탁들은 뇌물을 받거나 엉터리로 점을 쳐 그를 무죄로 방면해 주었다. 세월이 흘러 용병 대장에서 일약 전 이집트의 지배자로 등극한 아마시스는 기상천외한 방식으로 신전들을 정리했다.\n\n왕년에 자신이 도둑질했음을 정확히 맞혔던 신탁소에는 막대한 황금과 토지를 하사하며 참된 신의 거처로 떠받들었다. 반면 자신을 무죄라고 판결했던 엉터리 신탁소에는 \"신통력도 없는 거짓 우상에 불과하다\"며 제물을 전면 금지하고 신전 보수조차 막아 황폐하게 만들어 버렸다."
