    "yasaStory": "이집트를 여행하던 헤로도토스는 세상의 모든 강과 정반대로 움직이는 나일강을 보고 깊은 호기심에 빠졌다. 다른 강들은 겨울에 불어나고 여름에 마르는데, 나일강만은 유독 하지 무렵부터 물이 차올라 백 일 동안 대지를 적신 뒤 가을이 되어서야 가라앉기 때문이다.\n\n이집트 사제들에게 물어도 시원한 답을 얻지 못하자 그는 그리스 학자들이 내놓은 세 가지 학설을 꼼꼼히 따져보았다. 북풍이 물을 막아선다는 설, 땅을 둘러싼 대양에서 흘러온다는 설, 남쪽의 눈이 녹아내린다는 설이었지만, 헤로도토스는 \"사람 얼굴도 새까맣게 타는 불볕더위의 에티오피아에 무슨 눈이 쌓이겠는가\"라며 모두 논리적으로 기각했다.\n\n고심 끝에 그가 내린 결론은 이러했다. 겨울에는 폭풍우에 밀린 태양이 리비아 상공을 지나며 강물을 말려버리고, 여름이 되어 태양이 다시 북쪽으로 돌아가면 나일강이 비로소 본래의 수량을 회복한다는 것이다. 오늘날 관점에선 틀렸지만, 신화 대신 자연법칙으로 답을 찾으려 한 역사가의 치열한 탐구심이 빛난다."
