    "yasaStory": "고대 이집트에서 동물 살해는 엄격히 처벌받았으나 그중에서도 따오기와 매를 죽인 자는 고의든 실수든 참작 없이 무조건 사형에 처해졌다. 그만큼 이집트인들이 따오기(이비스)를 신성한 은인으로 여겼기 때문이다.\n\n헤로도토스가 들은 전승에 따르면, 매년 봄철 아라비아 협곡에서 등 뒤에 박쥐 같은 날개를 단 독사 무리가 나일강 계곡을 향해 새카맣게 날아들었다. 이때 협곡 입구를 지키고 서서 날아오는 독사 떼를 날카로운 부리로 모조리 쪼아 죽여 이집트를 지켜내는 것이 바로 검은 따오기 무리였다.\n\n따오기가 없었다면 온 이집트가 맹독의 뱀 떼로 인해 파멸했을 것이라 믿었던 백성들은 이 새를 지혜의 신 토트의 사자라 부르며 극진히 모셨다. 숨을 거둔 따오기는 사람과 똑같이 향유를 바르고 아마포로 감싸 미라로 만든 뒤 성도 헤르모폴리스의 신성한 묘역에 정중히 안치되었다."
