    "yasaStory": "가자에서 이집트 국경 펠루시움에 이르는 시나이 사막은 물 한 방울 나지 않는 죽음의 땅이었다. 아무리 막강한 페르시아 대군이라도 이 메마른 사막을 건너지 못하면 갈증으로 자멸할 수밖에 없었다.\n\n파네스의 조언을 들은 캄비세스는 사막의 패자인 아라비아 왕에게 사절을 보내 피로 맹세를 맺었다. 아라비아인들은 두 사람 사이에서 날카로운 돌로 엄지손가락을 째 흘러내린 피를 옷자락에 묻혀 바위에 바르며 디오니소스와 우라니아 신의 이름으로 결의를 다졌다.\n\n맹세를 지키기 위해 아라비아 왕은 셀 수 없이 많은 낙타의 등에 물을 가득 채운 낙타 가죽 부대를 싣고 사막 한복판으로 달려갔다. 그들은 페르시아군이 진군할 길목마다 거대한 급수 저수조를 파고 물을 채워 대군을 무사히 통과시켰다. 낙타 유목민들의 경이로운 보급 작전이 이집트 정복의 길을 열어준 것이다."
