    "yasaStory": "이집트 국경의 펠루시움 벌판에서 페르시아와 이집트 군세가 맞붙어 피비린내 나는 격전을 치렀다. 세월이 흘러 그 전장을 직접 찾은 헤로도토스는 양측 전사자들의 유골 무더기를 보며 기이한 광경에 주목했다.\n\n페르시아 병사들의 유골이 모인 곳에서는 작은 조약돌 하나만 가볍게 던져도 두개골이 달걀 껍데기처럼 바스러졌다. 그러나 이집트 병사들의 두개골은 큰 바윗돌로 힘껏 내리쳐도 흠집조차 나지 않을 만큼 단단했던 것이다.\n\n현지 사제들이 밝힌 이유는 머리를 다루는 양국의 오랜 습속 때문이었다. 이집트인들은 갓난아기 때부터 머리를 빡빡 깎아 강렬한 사막의 뙤약볕에 노출시켰기에 뼈가 두껍고 단단해졌으며 대머리가 되는 일도 없었다. 반면 페르시아인들은 어릴 적부터 두꺼운 털모자(티아라)를 눌러쓰고 햇볕을 피해 뼈가 연약하고 물러터졌던 것이다."
