    "yasaStory": "기원전 479년 플라타이아 평원에서 그리스와 페르시아 대군이 팽팽히 대치하던 11일째 밤, 아테네군 전초기지에 정체불명의 기마병 한 명이 홀로 말을 몰아 다가왔다. 그는 아테네 장군들을 만나야 한다며 중대한 비밀을 전하겠다고 청했다.\n\n장군들이 달려 나오자 그는 자신이 마케도니아의 왕 알렉산드로스라고 밝혔다. 어쩔 수 없이 페르시아 편에 서서 참전했으나, 그리스인으로서의 혈통과 동족에 대한 애정을 저버릴 수 없었던 것이다.\n\n알렉산드로스는 페르시아 사령관 마르도니오스가 불길한 점괘를 무시하고 날이 밝자마자 총공격을 감행할 것이라며, 페르시아군 역시 식량이 떨어져 오래 버티지 못하니 끝까지 항전하라고 일러주고 어둠 속으로 사라졌다. '필헬렌(그리스의 벗)'으로 불린 그의 목숨 건 밀고는 플라타이아 승리의 밑거름이 되었다."
