    "yasaStory": "크세르크세스가 본국으로 돌아간 뒤 그리스 정복의 전권을 물려받은 페르시아 총사령관 마르도니오스는 기원전 479년 여름 플라타이아에서 최후의 결전을 벌였다. 그리스군이 진영을 옮기며 대열이 흩어지자, 마르도니오스는 이를 후퇴로 오판하고 전군에 추격 명령을 내렸다.\n\n마르도니오스는 눈부신 백마를 타고 정예 기병 천 명에 둘러싸인 채 스파르타 보병들을 거칠게 몰아붙였다. 갑옷과 방패가 부서지는 난전 속에서도 백마 위 사령관이 버티는 동안 페르시아군은 물러서지 않았다.\n\n그러나 스파르타의 용사 아이임네스토스가 던진 돌에 머리를 정통으로 맞고 마르도니오스가 말에서 떨어져 숨을 거두자 전세는 순식간에 뒤집혔다. 사령관을 잃은 페르시아군은 뿔뿔이 흩어져 목책 진영으로 도망쳤고, 그리스 연합군의 맹공 앞에 대패하며 본토 침략 야망은 완전히 막을 내렸다."
