    "yasaStory": "흑해 북쪽 끝없는 초원을 누비던 스키타이 유목민들의 생명줄은 암말의 젖으로 빚어낸 독특한 음료 마유주(쿠미스)였다. 그들은 말을 착유할 때 기괴한 도구를 이용했다. 뼈로 만든 속이 빈 대롱을 암말의 은밀한 곳에 깊숙이 꽂고 입으로 힘껏 바람을 불어넣는 방식이었다.\n\n그렇게 입김을 불어넣으면 말의 핏줄이 팽창하고 젖통이 아래로 팽팽하게 차올라 젖이 폭포수처럼 쏟아져 나온다고 믿었다. 젖을 받아낸 뒤에는 깊은 나무통에 붓고 노예들로 하여금 쉬지 않고 통을 휘젓게 하여 거품과 응고물을 걸러냈다.\n\n스키타이인들은 이 말젖을 젓는 고된 일에 오직 전쟁 포로 노예들만 부렸다. 그리고 노예들이 광활한 초원에서 말을 훔쳐 달아나거나 가축을 다루는 부족의 비밀을 누설하지 못하도록, 끌려온 모든 포로의 두 눈을 불로 지져 멀게 만드는 잔인한 관습을 엄격히 고수했다."
