    "yasaStory": "아마존 여전사들과 스키타이 청년들의 결합으로 생겨난 사우로마타이 부족은 옛 어머니들의 호전적인 전통을 대대로 고스란히 계승했다. 그곳의 여인들은 가사 노동에 얽매여 천막에 머물던 다른 민족의 여인들과는 삶의 궤적이 완전히 달랐다.\n\n그들은 어린 시절부터 말을 능숙하게 다루고 사냥터를 질주했으며, 남편들과 대등하게 무장하고 전쟁터의 선봉에 서서 칼을 휘둘렀다. 옷차림 또한 사내들과 조금도 다를 바 없이 간결한 바지와 억센 가죽 갑옷을 걸치고 전장을 호령했다.\n\n특히 부족에는 처녀가 실제 전투에서 적 한 사람을 직접 죽여 전사로서의 무공을 증명하지 못하면 결코 시집갈 수 없다는 엄격한 규율이 내려왔다. 이 가혹한 율법을 채우지 못한 여인들은 아무리 나이가 들어 늙어갈지라도 남편을 얻지 못하고 쓸쓸히 처녀로 생을 마감해야 했다."
