    "yasaStory": "차가운 북풍의 신 보레아스가 부는 산맥 너머에는 전쟁과 질병을 모르는 신비의 낙원, 하이퍼보리아가 번영하고 있다고 전해졌다. 아폴론 신을 지극히 공경하던 그들은 밀짚 속에 꽁꽁 감싼 거룩한 예물을 에게해 델로스 섬의 아폴론 신전에 정기적으로 바치고자 했다.\n\n처음에는 두 처녀 히페로케와 라오디케에게 건장한 다섯 명의 호위 무사를 붙여 파견했다. 그러나 사절단이 머나먼 순례 길에 오른 뒤 다시는 고국으로 귀환하지 못하자, 왕국은 젊은이들을 잃을까 염려하여 기발한 대안을 마련했다.\n\n성스러운 밀짚 뭉치를 국경의 이웃 부족에게 넘겨주며 \"다음 민족에게 전해 달라\"고 간곡히 부탁하는 대륙 릴레이 전달 방식을 택한 것이다. 스키타이와 도나우강, 아드리아해를 거쳐 그리스 전역의 손에서 손으로 전해진 신비로운 밀짚 예물은 한 번도 도난당하지 않고 델로스 제단에 무사히 당도했다."
