    "yasaStory": "아르고스에서 쫓겨난 테메노스 가문의 삼 형제 중 막내 페르디카스는 마케도니아 레바이아의 왕 밑에서 양치기로 일했다. 형제들을 경계한 왕이 품삯도 주지 않고 내쫓으며, 굴뚝을 통해 방바닥에 내리쬔 햇빛을 가리켜 \"너희 품삯으로 저 햇빛이나 가져가라\"고 비웃었다.\n\n형들이 어이없어할 때 어린 페르디카스만은 달랐다. \"대왕님, 주시는 대로 감사히 받겠습니다\"라고 말한 뒤, 허리춤에서 단검을 뽑아 바닥에 비친 햇빛의 가장자리를 둥글게 그었다. 그러고는 두 손으로 햇빛을 세 번 떠서 자신의 옷자락 품에 고이 담고 방을 나섰다.\n\n신하로부터 그 의미를 들은 왕은 이 소년이 장차 온 땅의 주인이 될 징조임을 깨닫고 추격병을 보냈으나, 불어난 강물이 형제를 지켜주었다. 그 햇빛을 품은 소년이 바로 훗날 알렉산드로스 대왕을 낳은 마케도니아 아르게아스 왕조의 시조 페르디카스 1세였다."
