    "yasaStory": "바다에 던진 반지마저 생선 배 속에서 되돌아올 만큼 행운의 화신으로 불리던 사모스의 참주 폴리크라테스에게도 끝내 파멸의 그림자가 드리웠다. 사르디스의 페르시아 총독 오로이테스가 반란을 꾀하니 막대한 군자금을 나누자며 유인한 것이다.\n\n의심을 품은 폴리크라테스가 정탐꾼을 보내자, 총독은 돌로 가득 채운 상자 여덟 개 위에 금화만 얇게 덮어 보여 주며 감쪽같이 속였다. 황금에 눈이 먼 참주는 딸이 불길한 흉몽을 꾸고 말리는 것도 뿌리친 채 배에 올랐다.\n\n소아시아 땅을 밟자마자 붙잡힌 폴리크라테스는 처참하게 살해되어 말뚝에 매달렸고, 너무나 큰 행운은 결국 비극을 부른다는 고대인들의 경구가 현실이 되었다."
