    "yasaStory": "스키타이 기병들이 페르시아군보다 먼저 다뉴브 강에 도착해 부교를 지키던 이오니아 그리스 군주들을 설득했다. \"약속된 60일이 지났소. 다리를 끊고 돌아가시오. 페르시아 왕은 초원에서 죽을 것이며, 그대들은 자유를 얻을 것이오!\"\n\n아테네의 밀티아데스는 환호하며 다리를 끊자고 주장했다. 그러나 밀레토스의 참주 히스티아이오스가 은밀히 참주들을 모아놓고 정곡을 찔렀다. \"생각해 보시오. 우리가 백성을 누르고 참주 자리를 지키는 것은 오직 다리우스 대왕의 힘 때문이오. 대왕이 쓰러지면 백성들이 당장 우리를 몰아내고 민주정을 세울 것이오!\"\n\n참주들은 히스티아이오스의 말에 고개를 끄덕였다. 그들은 다리를 끊는 척 가장자리만 헐어 스키타이를 돌려보낸 뒤, 한밤중에 피투성이가 되어 도착한 대왕을 극적으로 건너게 했다."
