    "yasaStory": "트라키아 부족들 중에서도 가장 용맹하고 정의로운 부족으로 손꼽힌 게타이족에게는 세상 어디서도 찾아볼 수 없는 기이한 기상이 있었다. 험악한 먹구름이 몰려와 천둥이 울부짖고 대지에 벼락이 내리꽂히면, 부족민들은 두려움에 떨며 엎드리는 대신 일제히 팽팽한 활을 집어 들었다.\n\n그들은 성난 눈빛으로 번개가 번뜩이는 하늘을 매섭게 쏘아보며 맹렬하게 화살을 쏘아 올렸다. 허공을 향해 시위를 당기며 하늘에서 벼락을 내리는 정체불명의 신을 향해 감히 우리를 위협하지 말라며 당돌하게 맞불을 놓은 것이다.\n\n이들은 오직 자신들의 유일신 잘목시스 외에는 세상의 그 어떤 신도 신성한 존재로 인정하지 않았다. 거친 천재지변조차 칼과 활로 굴복시킬 수 있다고 믿었던 게타이인들의 불굴의 기개는 고대 그리스인들에게 크나큰 경이감을 불러일으켰다."
