    "yasaStory": "소아시아 프리기아의 옛 수도 켈라이나이 한복판에는 마이안드로스강과 카타락테스강이 세차게 솟아나는 깎아지른 절벽 성채가 자리 잡고 있었다. 그 성채 문루에는 지나가는 상인과 여행자들의 등골을 서늘하게 만드는 기괴한 물건이 걸려 바람에 나부끼고 있었다.\n\n그것은 바로 반인반수의 사티로스 마르시아스의 온전한 살가죽이었다. 아테나 여신이 뺨이 부풀어 오른다는 이유로 내던진 쌍피리를 주워 신들린 선율을 뽐내던 그는, 감히 올림포스의 태양신이자 리라의 지배자인 아폴론에게 음악 대결을 청하는 오만을 부렸다.\n\n신의 질투와 분노는 잔혹했다. 대결에서 승리한 아폴론은 그를 큰 소나무에 결박한 뒤 산 채로 가죽을 벗겨내 성문에 효수했다. 현지인들은 바람결에 프리기아 고유의 피리 가락이 흘러나올 때마다, 그 박제된 가죽이 마치 살아 숨 쉬듯 꿈틀거리며 춤을 춘다고 전했다."
