    "yasaStory": "스키타이 왕의 장례식은 초원 전체를 뒤흔드는 장엄하고도 섬뜩한 의식이었다. 왕이 숨을 거두면 배를 갈라 향료로 채운 뒤 각 부족을 순회하며 애도하게 하고, 첩과 술 따르는 시종, 요리사, 마부, 말들을 함께 순장해 거대한 봉분을 쌓았다.\n\n더욱 소름 돋는 의식은 1년 뒤에 치러졌다. 생전 왕을 모시던 젊은 시종 50명과 명마 50필을 목 졸라 죽인 다음, 내장을 빼내고 왕겨를 채워 박제처럼 만든 것이다.\n\n그들은 죽은 말의 등뼈를 따라 긴 나무 말뚝을 꽂고 바퀴 틀 위에 세운 뒤 시종 미라들을 말 위에 올려놓았다. 50명의 유령 기마병이 왕의 무덤을 둥글게 호위하는 광경은 초원을 지나는 이들에게 공포를 안겼다."
