    "yasaStory": "아테네의 전령 페이디피데스가 사흘 밤낮을 달려와 페르시아 대군의 침공을 알렸을 때, 스파르타인들은 종교 축제인 카르네이아 기간 동안 보름달이 차오르기 전에는 군대를 출병시킬 수 없다는 신성한 율법에 묶여 있었다.\n\n마침내 보름달이 밤하늘을 환하게 밝히고 금기가 풀리자마자, 2,000명의 최정예 스파르타 중장보병이 번개처럼 출격했다. 그들은 험준한 산악을 가로지르며 불과 사흘 만에 무려 220km에 달하는 거리를 주파하여 아티카 평원에 도착하는 경이적인 행군 속도를 과시했다.\n\n그러나 그들이 마라톤 평원에 도착했을 때, 전투는 이미 아테네의 단독 대승으로 끝난 뒤였다. 동방의 대군과 자웅을 겨루고 싶어 했던 스파르타 전사들은 평원에 산더미처럼 널브러진 페르시아 전사들의 시신들을 호기심 어린 눈으로 둘러보고, 아테네인들의 무공을 아낌없이 칭송한 뒤 쓸쓸히 귀국길에 올랐다."
