    "yasaStory": "유라시아 스텝 지대의 끝, 얼어붙은 북풍이 불어오는 리파이오스 산맥 너머에는 전설의 종족 '아리마스포이'가 산다고 전해졌다. 스키타이어로 '아리마'는 하나, '스포우'는 눈을 뜻하니, 말 그대로 이마 한가운데에 눈이 하나뿐인 외눈박이 전사들이었다.\n\n프로콘네소스의 시인 아리스테아스가 신들린 듯 북방을 여행하고 돌아와 남긴 서사시에 따르면, 이들 너머에는 맹금의 부리와 사자의 몸을 지닌 괴수 '그리핀'이 황금 광맥을 지키고 있었다. 아리마스포이족은 말에 올라타 그리핀의 둥지로 돌진해 황금을 빼앗으려 목숨 건 싸움을 벌였다.\n\n헤로도토스는 한 번도 직접 보지 못한 외눈박이 인간이 정말 존재하는지 의심스러워했다. 하지만 북유럽과 중앙아시아에서 유입되던 막대한 황금의 출처를 상상하던 고대 그리스인들에게, 황금과 괴수와 외눈 거인의 이야기는 끝없는 매혹을 안겨 주었다."
