    "yasaStory": "기원전 499년, 페르시아에 맞서 반란을 준비하던 밀레토스의 아리스타고라스가 본토 최강국 스파르타를 찾았다. 그의 손에는 당시로서는 경이로운 물건인 '세계 지도'가 새겨진 청동판이 들려 있었다. 육지와 바다, 수많은 강줄기가 새겨진 지도를 짚어 가며 그는 스파르타 왕 클레오메네스 1세를 설득했다.\n\n\"페르시아인은 창과 방패가 약해 정복하기 쉽고, 수사에는 황금이 산처럼 쌓여 있습니다!\" 솔깃해진 왕이 사흘의 고민 끝에 물었다. \"이오니아 바다에서 페르시아 왕궁까지 걸어서 며칠이나 걸리느냐?\"\n\n화술에 능하던 아리스타고라스가 그만 아차 하고 진실을 말하고 말았다. \"석 달 걸립니다.\" 그 말이 떨어지자마자 클레오메네스의 얼굴이 굳었다. \"여봐라, 밀레토스 손님! 해가 지기 전에 당장 스파르타를 떠나라. 스파르타군을 바다에서 석 달 거리나 떨어진 곳으로 끌어내려 하다니!\" 정직한 한마디가 외교의 문을 닫아 버린 순간이었다."
