    "yasaStory": "기원전 498년, 이오니아 반란군과 아테네 원정군이 페르시아의 서방 거점 사르디스를 기습해 불태웠다는 급보가 대왕 다리우스 1세에게 날아들었다. 보고를 받은 대왕은 반란을 일으킨 이오니아인들보다 낯선 이름에 먼저 눈을 부라렸다. \"아테네인이란 도대체 누구냐?\"\n\n그들이 바다 건너 작은 도시국가 사람들이라는 답을 듣자 다리우스의 자존심이 무너졌다. 그는 즉시 활과 화살을 가져오게 하더니, 시위를 당겨 하늘을 향해 화살을 쏘아 올리며 외쳤다. \"오, 신이시여! 제가 아테네인들에게 반드시 복수할 수 있게 허락하소서!\"\n\n그날 이후 페르시아 왕궁의 식탁에는 기이한 의식이 생겼다. 다리우스는 시종 한 명을 시켜 자신이 식사 자리에 앉을 때마다 세 번씩 큰 소리로 외치게 했다. \"주군, 아테네인을 기억하소서!\" 한 번의 원한을 매일 세 번씩 되새긴 대왕의 집념은 결국 기원전 490년 마라톤 평원으로 향하는 대원정으로 이어졌다."
