    "yasaStory": "크세르크세스 1세가 그리스 침공을 결정하기 전 어전회의를 열었을 때, 모든 신하가 아첨하며 출병을 찬양했다. 오직 선왕 다리우스의 동생이자 왕의 숙부인 노재상 아르타바노스만이 홀로 일어서서 반기를 들었다. 그는 일찍이 스키티아 원정 실패를 목격했던 경험을 상기시키며 조카에게 간곡히 충언했다.\n\n\"전하, 신께서는 홀로 위대해지고자 하시기에 가장 키 큰 짐승과 가장 높이 솟은 나무와 궁궐에 벼락을 내리십니다. 아무리 거대한 군대라도 하찮은 질병이나 공포에 휩싸여 패망할 수 있습니다.\" 아르타바노스는 인간의 한계를 넘는 과도한 번영과 오만은 반드시 신의 질투를 부른다고 눈물로 호소했다.\n\n분노한 크세르크세스는 숙부를 비겁자라 몰아세우며 수사에 홀로 남아 궁궐이나 지키라고 모욕했다. 그러나 그날 밤 왕은 홀로 침상에 누워 숙부의 깊은 경고가 머릿속을 맴돌자 비로소 깊은 번민과 두려움에 사로잡혔다."
