    "yasaStory": "숙부 아르타바노스의 충언을 듣고 그리스 원정을 취소하기로 결심한 날 밤, 크세르크세스의 침상에 키가 크고 위엄 있는 한 남자의 환영이 나타났다. 그 유령은 왕을 굽어보며 \"페르시아의 왕이여, 군대를 소집해 놓고 어찌 마음을 바꾸는가? 그대의 운명은 이미 정해졌으니 원정을 떠나라\"고 위협했다.\n\n다음 날 아침 왕은 유령의 말을 무시하고 신하들에게 전쟁 취소를 선포했다. 하지만 이튿날 밤 유령은 더 무서운 형상으로 다시 나타나 왕을 꾸짖었다. \"만약 즉시 원정을 개시하지 않는다면, 그대가 지금 높은 자리에 오른 것처럼 순식간에 가장 비천한 자리로 떨어지게 되리라.\"\n\n공포에 질린 왕은 숙부 아르타바노스에게 왕관과 옷을 입히고 자신의 옥좌와 침상에 눕혀 시험해 보게 했다. 놀랍게도 그 유령은 숙부의 꿈에도 나타나 달군 쇠꼬챙이로 눈을 멀게 하겠다고 협박했고, 결국 두 사람은 거스를 수 없는 신의 뜻이라 여기며 출병을 강행했다."
