    "officialRecord": "페르시아 제국이 헬레스폰토스 해협에 674척의 군선을 띄우고 페니키아의 아마포와 이집트의 파피루스 거대 닻줄로 엮어 기적의 부교를 완성한 공학적 기록이다.",
