    "yasaStory": "기원전 480년 봄, 사르디스에서 겨울을 보낸 페르시아의 100만 대군이 마침내 그리스를 향해 웅장한 행진을 시작했다. 황금 전차와 화려한 깃발이 온 들판을 뒤덮은 순간, 구름 한 점 없는 맑은 하늘에서 갑자기 태양이 빛을 잃고 칠흑 같은 어둠이 대지를 덮쳤다.\n\n한낮에 별이 드러나자 대열 전체가 불길한 징조에 휩싸여 전율했다. 두려움에 사로잡힌 크세르크세스는 페르시아의 예언자이자 제사장인 마기(Magi)들을 불러 모아 이 기이한 천문 현상의 의미를 다급히 물었다.\n\n마기 사제들은 왕의 안색을 살피며 능숙하게 예언을 꾸며냈다. \"전하, 태양은 그리스의 수호신 아폴론을 상징하고 달은 우리 페르시아의 상징입니다. 신께서 태양을 가리셨으니 이는 곧 그리스 도시들의 빛이 꺼지고 멸망할 징조이옵니다.\" 왕은 기뻐하며 안도했고, 어두운 하늘 아래서 거대한 파멸의 행진을 멈추지 않았다."
