    "yasaStory": "그리스 원정군을 이끌고 진격하던 크세르크세스 대왕은 테살리아의 장엄한 템페 협곡 앞에 멈춰 서서 탄성을 내질렀다. 올림포스산과 오사산이 깎아지른 절벽을 이루며 맞닿아 있고, 그 좁은 바위틈 사이로 페네이오스 강이 푸른 물결을 일으키며 에게 해로 빠져나가고 있었다.\n\n테살리아 원주민들은 이 비경을 두고 포세이돈의 기적이라 전했다. 아득한 옛날 테살리아 전체는 사방이 높은 산맥으로 둘러싸여 물이 빠져나가지 못하는 거대한 내륙 호수였다. 대지의 신 포세이돈이 거대한 삼지창을 내리쳐 산맥을 두 조각으로 쪼개자, 갇혀 있던 호숫물이 거센 폭포처럼 바다로 쏟아져 나가며 비옥한 평야가 드러났다는 것이다.\n\n지세를 유심히 살피던 크세르크세스는 서늘한 미소를 지었다. \"테살리아인들이 일찌감치 내게 복종한 것은 참으로 현명한 처사였다. 저 좁은 바위틈만 흙으로 메워버리면 온 나라를 하룻밤 사이에 다시 호수로 수몰시킬 수 있지 않겠는가.\" 대왕의 오만한 감탄 속에 자연의 신비가 서려 있었다."
