    "yasaStory": "코린토스를 독점 지배하던 바키아다이 귀족 가문은 델포이 신탁을 듣고 충격에 빠졌다. 가문의 여인 라브다가 낳을 아들이 훗날 자신들을 몰아낼 것이라는 예언이었다. 아기가 태어나자 귀족들은 즉시 자객 열 명을 보내 첫 번째로 아기를 안는 자가 땅에 내동댕이쳐 죽이기로 약조했다.\n\n라브다의 집에 들이닥친 자객 중 우두머리가 아기를 건네받았다. 그런데 바로 그 순간, 갓난아기가 자객의 얼굴을 올려다보며 해맑게 방긋 웃었다. 차마 아기를 던지지 못한 그는 다음 동료에게 아기를 넘겼고, 아기는 두 번째, 세 번째 자객에게도 똑같이 미소를 지었다. 결국 열 명 모두가 마음을 약하게 먹어 아기를 어머니에게 돌려주고 밖으로 나왔다.\n\n문밖에서 서로를 탓하며 다시 들어가려던 찰나, 대화를 엿들은 라브다가 아기를 커다란 삼나무 상자(퀴프셀레) 속에 숨겼다. 상자 덕분에 목숨을 건진 아기는 훗날 '퀴프셀로스'라 불리며, 신탁대로 귀족들을 몰아내고 코린토스의 참주가 되었다."
