    "yasaStory": "크세르크세스 대군의 중심에는 히다르네스가 지휘하는 1만 명의 정예 보병대, 이른바 '아타나토이(불사부대)'가 있었다. 이들이 불사부대로 불린 이유는 죽지 않는 마법을 지녀서가 아니라, 전사자나 병자가 생기면 그 즉시 예비 병력에서 정확히 한 명을 차출해 채워 넣음으로써 언제나 단 한 명도 넘치거나 모자람 없이 만 명을 유지했기 때문이다.\n\n이들은 제국 전역에서 선발된 순수 페르시아 혈통의 귀족들로 구성되었다. 눈부신 비단옷 위에 정교한 철제 비늘 갑옷을 덧입고, 석류 모양의 은제 손잡이가 달린 창과 갈대 화살통을 메고 전장을 누볐다.\n\n그중에서도 최선두 천 명의 지휘관들은 창자루 끝에 순금 석류를 달아 황실의 절대적인 부와 권세를 과시했다. 그들의 뒤에는 화려하게 꾸민 마차와 시종들이 따르며 전용 식량을 운반했으니, 그 행렬은 전사들의 군대이자 움직이는 황금 궁전과도 같았다."
