    "yasaStory": "도리스코스에서 사열을 마친 크세르크세스는 자신만만하게 스파르타의 전 국왕이자 망명객인 데마라토스를 불렀다. \"그리스인들이 감히 내 거대한 군대와 맞서 싸울 수 있겠는가?\" 왕은 그리스의 미미한 병력으로는 페르시아의 군세를 감당하지 못할 것이라 단언했다.\n\n데마라토스는 왕의 노여움을 살 각오를 하고 솔직한 진실을 고했다. \"전하, 그리스는 가난을 벗삼아 지혜와 엄격한 법률로 용기를 길러왔습니다. 특히 스파르타인들은 페르시아군이 천 명이든 수백만이든 상관없이 반드시 전하와 싸울 것입니다.\"\n\n크세르크세스가 채찍으로 다스리는 주인도 없는 자들이 어떻게 목숨을 바치느냐며 비웃자, 데마라토스는 명언을 남겼다. \"그들은 자유롭지만 완전한 자유인은 아닙니다. 그들에게는 전하보다 훨씬 무서운 주인, 바로 '법(Nomos)'이 있습니다. 그 법은 어떤 적 앞에서도 도망치지 말고 자리를 지켜 승리하거나 죽으라고 명합니다.\""
