    "yasaStory": "페르시아가 그리스 본토에서 패퇴한 뒤에도 트라키아의 스트뤼몬 강 하구에 자리 잡은 에이온 요새는 총독 보게스의 지휘 아래 끈질기게 버티고 있었다. 아테네의 명장 키몬이 군대를 몰고 와 요새를 완전히 포위하고 항복하면 본국으로 무사히 보내주겠다고 제안했으나, 보게스는 대왕을 배신하는 비겁자가 될 수 없다며 완강히 거절했다.\n\n식량이 완전히 바닥나고 함락이 코앞으로 다가오자 보게스는 비장한 결단을 내렸다. 그는 성내에 있던 금과 은, 모든 값진 보물들을 긁어모아 깊은 스트뤼몬 강물 속으로 던져버렸다. 그리스인들이 단 한 조각의 전리품도 챙기지 못하게 하려는 것이었다.\n\n이어 그는 요새 한복판에 거대한 장작더미를 쌓아 올리고 불을 질렀다. 보게스는 아내와 자식들, 첩들과 가신들을 모두 칼로 찔러 불길 속에 던져 넣은 뒤, 자신 역시 활활 타오르는 화염 속으로 몸을 던졌다. 그의 죽음 소식을 들은 크세르크세스 대왕은 눈물을 흘리며 살아남은 그의 유족들에게 제국 최고의 영예를 내렸다."
