    "yasaStory": "기원전 490년, 페르시아 대군이 마라톤 해안에 닻을 내리자 다급해진 아테네는 최고의 장거리 주자 페이디피데스를 스파르타로 급파했다. 아테네에서 스파르타까지는 험준한 산악 길을 넘어 약 240킬로미터. 페이디피데스는 출발한 지 단 이틀 만에 스파르타에 도착하는 경이로운 질주를 해냈다.\n\n훗날 시인들이 그를 마라톤에서 아테네까지 달려 승전을 알리고 숨진 인물로 각색했지만, 헤로도토스가 기록한 진짜 이야기는 스파르타로 가는 산길에서 일어났다. 테게아 위쪽 파르테니온 산을 넘던 중, 염소 다리를 한 목축의 신 '판'이 그의 이름을 크게 부른 것이다.\n\n\"페이디피데스야, 어찌하여 아테네인들은 나를 돌보지 않느냐? 나는 늘 아테네를 아끼고 앞으로도 도울 것인데.\" 스파르타가 종교 축제를 핑계로 출병을 미루는 바람에 아테네는 홀로 싸워야 했지만, 마라톤 대승 직후 아테네인들은 전령의 말을 믿고 아크로폴리스 아래 동굴에 판 신전을 세웠다."
