    "yasaStory": "새벽녘 배후가 뚫렸다는 척후병의 다급한 보고가 전해지자 그리스 연합군 지휘관들은 격론을 벌였다. 대부분의 도시는 포위를 피해 후퇴를 주장했으나, 스파르타의 국왕 레오니다스는 법률과 전사의 명예에 따라 자리를 떠날 수 없음을 분명히 했다.\n\n레오니다스는 다른 도시의 군사들에게 불필요한 죽음을 피하고 훗날을 도모하라며 전장을 떠나도록 명했다. 이에 펠로폰네소스의 동맹군들은 고향으로 철수했으나, 데모필로스가 이끄는 700명의 테스피아이인들은 레오니다스를 버리고 떠나기를 단호히 거부하며 끝까지 함께 남았다.\n\n신탁은 \"스파르타의 왕이 죽지 않으면 스파르타가 멸망하리라\"고 예언한 바 있었다. 레오니다스는 자신의 죽음으로 조국을 구하고 동맹군을 살리려는 숭고한 결단으로, 협곡의 좁은 벽 사이에서 테스피아이의 벗들과 함께 불멸의 최후를 준비했다."
