    "yasaStory": "마지막 날 아침, 레오니다스는 더 이상 좁은 방어벽 뒤에 숨지 않고 협곡의 넓은 곳으로 뛰어나가 적진을 향해 돌진했다. 죽음을 결심한 전사들은 광기에 가까운 용기로 페르시아 군대를 도륙했고, 뒤에서 채찍질로 병사들을 몰아넣던 페르시아 장수들까지 추풍낙엽처럼 쓰러졌다.\n\n치열한 격전 중에 레오니다스가 전사하고, 스파르타군이 소지한 무거운 청동 장창들이 부러져 나갔다. 그들은 단검을 뽑아 휘둘렀으나 칼마저 부러져 자루만 남게 되자, 전사들은 작은 언덕 위로 모여들어 둥근 방진을 쳤다.\n\n칼이 없으면 부러진 칼날로, 칼날마저 부러지면 주먹과 맨손으로, 심지어 입으로 적의 살점을 물어뜯으며 끝까지 버텼다. 페르시아군은 감히 접근하지 못하고 사방에서 화살과 투창을 쏟아부었고, 언덕 위의 영웅들은 빗발치는 무기 아래 파묻히며 장렬한 최후를 마쳤다."
