    "yasaStory": "아테네 민주주의의 기틀을 닦은 클레이스테네스와 명재상 페리클레스를 배출한 명문 알크마이온 가문. 이 가문이 단숨에 그리스 최고의 부호가 된 데에는 조상 알크마이온의 유쾌한 일화가 숨어 있다.\n\n리디아의 황금왕 크로이소스가 사절들을 환대한 보답으로 알크마이온을 불러 호의를 베풀었다. \"보물 창고에 들어가 단 한 번에 몸에 지니고 나올 수 있는 만큼 황금을 가져가시오.\" 알크마이온은 그 기회를 놓치지 않았다. 그는 가장 헐렁하고 품이 넓은 옷과 제일 큰 장화를 신고 보물고로 들어갔다.\n\n먼저 장화 속 빈틈에 사금을 가득 채워 넣고, 옷자락의 주머니마다 금가루를 쓸어 담았다. 그것도 모자라 머리카락 사이사이에 금가루를 뿌리고, 심지어 입안 두 볼이 터질 듯이 황금을 물고 비틀거리며 걸어 나왔다. 사람의 몰골이 아닌 기괴한 모습으로 뒤뚱거리는 그를 보고 크로이소스는 폭소를 터뜨렸고, 기분이 좋아져 그만큼의 황금을 한 번 더 얹어 주었다."
