    "title": "탁자 위에서 물구나무 춤을 추다 혼사를 날린 뒤 '그게 무슨 상관!'",
    "officialRecord": "시키온의 사윗감 경합에서 1순위였던 아테네 귀족 히포클레이데스는 연회에서 탁자 위 물구나무 춤을 추다 파혼당하자 '히포클레이데스는 상관없소'라는 명언을 남겼다.",
