    "title": "동료 왕을 몰아내고 사제까지 매수했다가 광기 속에 죽은 스파르타 왕",
    "officialRecord": "스파르타의 클레오메네스 1세는 동료 왕 데마라토스를 축출하기 위해 델포이 신탁의 여사제까지 매수했으나, 비밀이 탄로 나 망명했다가 돌아온 뒤 미쳐서 자해로 사망했다.",
