    "yasaStory": "두 명의 왕이 함께 나라를 다스리는 스파르타에서, 아기아스 가문의 클레오메네스 1세는 사사건건 맞서는 공동 왕 데마라토스를 눈엣가시처럼 여겼다. 결국 그는 데마라토스의 출생 비밀을 문제 삼아 델포이 신전으로 문제를 넘겼다.\n\n클레오메네스는 신전의 유력자 코본을 통해 여사제 피티아를 몰래 매수했고, 신탁은 \"데마라토스는 왕의 아들이 아니다\"라는 판결을 내렸다. 쫓겨난 데마라토스는 페르시아로 망명하고 말았다. 그러나 신성한 신탁을 돈으로 샀다는 추문이 세상에 드러나자, 클레오메네스 역시 스파르타를 떠나 망명길에 올라야 했다.\n\n이웃 아르카디아에서 군사를 모아 스파르타를 위협하던 그는 두려워진 본국의 소환을 받아 복귀했다. 하지만 왕좌로 돌아오자마자 그는 미쳐 버렸다. 길에서 마주치는 스파르타 시민의 얼굴을 지팡이로 내리치는 기행을 일삼다 가족들에 의해 나무 족쇄에 묶였고, 결국 감시하던 노예를 협박해 칼을 빼앗은 뒤 스스로 다리부터 배까지 난도질해 비참하게 숨을 거두었다."
