    "yasaStory": "테르모필레가 함락되고 페르시아 대군이 아티카로 물밀듯이 밀려오자 아테네는 공포에 휩싸였다. 그때까지도 조상의 땅을 떠나기를 망설이던 시민들에게 아크로폴리스 신전으로부터 충격적인 징조가 전해졌다.\n\n에렉테이온 신전의 지하에는 아테네 도시를 지키는 거대한 뱀이 살고 있다고 믿어져, 여사제들은 매달 그 뱀을 위해 꿀로 반죽한 떡을 제단에 바쳐왔다. 그런데 페르시아군이 진격해 오던 바로 그달, 제단에 올려놓은 꿀떡이 손 하나 대지 않은 채 그대로 남아 있었던 것이다.\n\n수호 뱀이 자취를 감추고 음식을 거부했다는 소식은 아테나 여신이 마침내 아크로폴리스를 버리고 떠났다는 명백한 징표로 받아들여졌다. 이에 시민들은 미련을 버리고 처자식과 노인들을 배에 태워 살라미스섬과 트로이젠으로 신속히 탈출했고, 텅 빈 도시는 페르시아군의 화염 속에 휩싸였다."
