    "yasaStory": "기원전 490년 마라톤 평원, 페르시아군 6,400명이 쓰러진 치열한 백병전 속에서 아테네군 역시 192명의 전사자를 냈다. 그 아수라장에서 맹렬히 창을 휘두르던 아테네 병사 에피젤로스에게 기이한 일이 벌어졌다.\n\n칼에 베인 적도, 날아온 화살이나 돌에 맞은 적도 없었는데, 그의 두 눈이 순식간에 캄캄하게 멀어 버린 것이다. 훗날 앞을 보지 못한 채 살아가던 에피젤로스는 사람들에게 자신이 전장에서 목격한 섬뜩한 광경을 들려주었다.\n\n눈앞에 인간이라고는 믿기지 않을 만큼 거대한 중장보병의 환영이 나타났는데, 그 거인의 턱수염이 방패 전체를 뒤덮을 정도였다고 했다. 그 거대한 그림자는 에피젤로스를 스쳐 지나가더니 바로 옆에 서 있던 전우를 베어 죽였고, 그 순간 에피젤로스의 시야는 영원히 닫혀 버렸다. 헤로도토스는 마라톤의 승리가 단순한 인간의 싸움을 넘어 신비로운 기운이 감돌던 현장이었음을 이 증언으로 전했다."
