    "yasaStory": "살라미스 승리 직후 아테네인들은 곧장 헬레스폰토스로 진격해 페르시아의 배다리를 끊고 적을 가두자고 주장했다. 그러나 테미스토클레스는 도망가는 맹수를 몰아세우면 결사 항전할 수 있다며 추격을 만류하는 척하면서, 은밀히 자신의 개인적인 보험을 들었다.\n\n그는 일전에 거짓 투항 정보로 크세르크세스를 살라미스로 유인했던 충복 시킨노스를 다시 페르시아 왕에게 밀사로 보냈다. 밀서의 내용은 대담하기 짝이 없었다. \"왕이여, 그리스군이 다리를 끊으려던 것을 내가 왕을 위해 극구 말리고 퇴로를 열어두었으니 안심하고 귀환하시오.\"\n\n왕의 신임을 얻어 훗날 그리스에서 버림받을 경우를 대비한 테미스토클레스의 소름 돋는 이중 플레이였다. 실제로 수년 뒤 아테네에서 도편추방을 당해 쫓겨난 그는, 이 편지를 근거로 페르시아 궁정으로 망명하여 영지를 하사받고 부귀를 누렸다."
