    "yasaStory": "플라타이아 벌판에서 열흘이 넘도록 대치가 이어지던 한여름, 그리스 연합군에게 가장 치명적인 재앙이 닥쳐왔다. 아소포스 강변은 페르시아 궁수들의 사정거리 안에 있어 접근할 수 없었고, 연합군 수만 명이 마실 물은 진영 뒤편의 가르가피아 샘 하나에 전적으로 의존하고 있었다.\n\n그리스군의 고통을 간파한 마르도니오스는 날랜 기병대를 휘몰아 가르가피아 샘으로 돌진시켰다. 페르시아 기병들은 그리스 수비대를 화살로 몰아낸 뒤, 말발굽으로 샘터를 마구 짓밟아 맑은 물을 흙탕물과 오물로 뒤섞어버렸다. 펠로폰네소스에서 올라오던 식량 수송대마저 산길에서 차단당하자 연합군은 굶주림과 극심한 갈증에 휩싸였다.\n\n사령관 파우사니아스와 그리스 지휘관들은 더는 버틸 수 없다고 판단했다. 마실 물이 솟는 플라타이아 근교의 '섬'이라 불리는 지형으로 진지를 옮기기로 결의하고, 한밤중 어둠을 틈타 퇴각 작전을 시작했다. 그러나 이 퇴각은 전선에 혼란을 불러일으켰고, 다음 날 아침 운명을 건 대회전으로 이어졌다."
