    "imageUrl": "",
    "yasaStory": "플라타이아의 결전이 절정에 달했을 때, 전장의 한가운데에는 페르시아 총사령관 마르도니오스가 있었다. 그는 눈부신 백마에 올라타 1천 명의 정예 호위병에게 둘러싸인 채, 화살과 창이 빗발치는 최전선을 누비며 직접 전투를 지휘했다. 총사령관이 당당히 버티고 서 있는 한 페르시아 전사들은 결코 물러서지 않고 맹렬히 저항했다.\n\n하지만 승리의 여신은 그리스의 손을 들어주었다. 격전의 소용돌이 속에서 스파르타의 용사 아임네스토스가 빈틈을 포착했다. 그는 땅에서 묵직한 돌을 집어 들어 온 힘을 다해 마르도니오스의 머리를 겨누고 내던졌다.\n\n돌은 투구를 비껴 마르도니오스의 머리에 명중했고, 총사령관은 피를 뿜으며 말 아래로 곤두박질쳤다. 그를 결사적으로 호위하던 1천 명의 근위대마저 모조리 쓰러지자, 사령관의 전사를 목격한 페르시아 전군은 공포에 질려 무기를 내던지고 목책 요새를 향해 뿔뿔이 도망치기 시작했다."
