    "yasaStory": "마르도니오스가 쓰러진 뒤 살아남은 페르시아 군사들은 아소포스 강 너머 미리 쌓아두었던 거대한 목책 요새 안으로 숨어들었다. 높은 망루와 두터운 나무 성벽 뒤에서 적들이 활을 쏘아대자, 먼저 도착한 스파르타군은 요새를 함락시키지 못한 채 방벽 아래서 발이 묶였다. 스파르타인들은 평야의 회전에는 무적이었으나 공성전에는 서툴렀다.\n\n전세가 답답하게 늘어지던 찰나, 보에오티아 연합군을 격파한 아테네군이 요새 앞에 당도했다. 공성 기술에 잔뼈가 굵은 아테네 중장보병들은 즉각 스파르타군과 합세하여 맹렬하게 목책을 들이쳤다.\n\n마침내 아테네 병사들이 목책의 한 귀퉁이를 부수고 성벽 위로 기어오르는 데 성공했다. 성벽이 뚫려 연합군이 쏟아져 들어오자 요새 안은 쥐덫에 갇힌 도살장으로 변했다. 공포에 질려 무기조차 쥐지 못한 페르시아군은 연합군의 칼날 아래 쓰러졌고, 30만 대군 중 살아서 도망친 자는 손에 꼽힐 정도였다."
