    "yasaStory": "기원전 480년 크세르크세스의 대군이 밀려오자 공포에 질린 아테네 사절단은 델포이 신전을 찾았다. 첫 신탁은 '아테네는 불타리라'는 절망적인 예언뿐이었지만, 사절단이 올리브 가지를 들고 다시 간청하자 여사제 피티아는 '오직 나무 성벽만이 무너지지 않고 너희를 지키리니, 신성한 살라미스가 여인들의 자식들을 멸하리라'는 수수께끼를 내놓았다.\n\n아테네 민회는 둘로 갈렸다. 원로들은 아크로폴리스 주변의 옛 나무 울타리를 뜻한다고 여겼으나, 테미스토클레스의 생각은 달랐다. 그는 신탁이 살라미스를 '비참한'이 아니라 '신성한'이라 부른 점에 주목하며, 아테네를 지킬 나무 성벽은 바로 라우레이온 은광의 수익으로 건조한 200척의 삼단노선이라고 역설했다.\n\n결국 아테네인들은 도시를 비우고 바다로 나가는 대담한 도박을 선택했다. 이 해석은 훗날 살라미스 해전의 대승으로 이어져 아테네 해양 제국의 초석이 되었다."
