    "yasaStory": "플라타이아 대첩이 끝난 뒤 그리스인들은 페르시아군이 버리고 간 막대한 전리품을 수습했다. 황금과 은, 말과 낙타, 그리고 셀 수 없이 많은 청동 투구와 방패가 쏟아져 나왔다. 연합군은 전리품의 십분의 일을 떼어 신들에게 바치기로 결정하고, 청동 무기들을 거대한 화로에 녹였다.\n\n그들은 이 청동을 부어 세 마리의 거대한 뱀이 몸통을 꼬며 하늘로 솟아오르는 신비로운 형상의 기둥을 만들었다. 뱀들의 세 머리가 받치고 있는 꼭대기에는 순금으로 빚은 황금 솥(삼각정)이 찬란하게 얹혀 델포이 아폴론 신전에 봉헌되었다.\n\n처음에는 총사령관 파우사니아스가 자신이 적을 섬멸했다는 오만한 글귀를 새겼으나, 스파르타 정부는 동맹군들의 거센 반발을 사자마자 그의 이름을 깎아내 버렸다. 그 대신 뱀 기둥의 구불구불한 청동 몸통 위에는 조국을 지키기 위해 함께 피를 흘렸던 서른한 개 그리스 폴리스의 이름이 영원히 새겨졌다."
