    "yasaStory": "플라타이아의 참혹한 살육전이 끝나고 그리스 전역에는 해방의 환호성이 울려 퍼졌다. 연합군은 야만인 침략자들을 물리친 승리가 인간의 힘만으로 이뤄진 것이 아니라 신들의 은총 덕분임을 고백하며 전리품의 십분의 일을 모아 세 곳의 성소에 바쳤다.\n\n올림피아의 제우스 신전에는 높이가 10큐빗(약 4.5미터)에 달하는 거대한 청동 제우스 상이 우뚝 솟아올랐다. 코린토스만의 유서 깊은 폴리스 시키온을 비롯해 어깨를 겯고 싸웠던 펠로폰네소스의 전사들은 전리품 청동을 정성껏 녹여 신전에 바칠 청동 제기와 봉헌물들을 빚어냈다.\n\n그 청동 제기들에는 침략자의 칼날 앞에서도 물러서지 않고 자유를 지켜낸 도시들의 이름이 깊게 아로새겨졌다. 이후 올림피아 제전에 모여든 그리스인들은 햇빛에 찬연히 빛나는 청동 봉헌물을 바라보며, 민족의 운명을 갈랐던 그 위대한 여름날의 희생과 승리를 대를 이어 기렸다."
