    "yasaStory": "스키타이인들이 전하는 자신들의 건국 신화에 따르면, 최초의 인간 타르기타오스에게는 세 아들이 있었다. 어느 날 세 형제가 광활한 초원에 서 있을 때 하늘이 갈라지며 순금으로 빚은 네 가지 신성한 보물이 떨어져 내렸다. 그것은 쟁기와 멍에, 전투용 도끼와 술잔이었다.\n\n맏아들 리폭사이시스가 신기한 황금을 거두기 위해 다가가자, 황금에서 맹렬한 불길이 치솟아 올라 접근을 가로막았다. 놀란 둘째 아르폭사이시스가 다가섰을 때도 황금은 다시 활활 타오르며 그를 밀어냈다.\n\n하지만 막내 콜락사이시스가 성큼성큼 다가가자 기적처럼 불길이 순식간에 꺼졌다. 막내는 아무런 화상도 입지 않은 채 차가워진 황금 보물들을 두 손으로 번쩍 들어 올렸다. 형들은 신의 뜻이 막내에게 있음을 깨닫고 왕권을 그에게 양보했다. 이 막내의 핏줄에서 초원을 호령한 지배 부족, '왕족 스키타이인'이 시작되었다."
