    "yasaStory": "페르시아가 메디아를 무너뜨리고 아시아의 패권을 차지했을 때, 귀족 아르템바레스가 키루스 대제를 찾아와 달콤한 제안을 건넸다. \"우리가 온 세상의 주인이 되었으니, 이제 척박하고 메마른 고향 산악지대를 떠나 저 기름지고 비옥한 평야 지대로 터전을 옮겨 낙원을 누립시다.\"\n\n신하들의 눈빛이 기대감으로 빛났으나 키루스 대제는 웃지 않았다. 대제는 그들의 청을 허락하겠다면서도 서늘한 경고를 덧붙였다. \"그렇게 하라. 다만 이제는 남을 지배하는 자가 아니라 남의 지배를 받는 노예가 될 준비를 단단히 해야 할 것이다.\"\n\n대제는 역사를 꿰뚫는 불멸의 통찰을 남겼다. \"기름지고 부드러운 땅에서는 부드럽고 나약한 인간이 태어나는 법이다. 한 토양에서 탐스러운 열매와 강인한 전사가 동시에 자라날 수는 없다.\" 이 준엄한 가르침 앞에 페르시아인들은 부끄러워하며 물러났고, 비옥한 땅의 노예가 되기보다 거친 땅의 주인으로 남기를 택했다."
